// Join the caller's W3C trace. n8n's own OpenTelemetry module parents its
// workflow.execute span on the same inbound `traceparent`, so the spans this
// workflow reports (root + generations) and n8n's workflow/node spans share
// one trace id in Langfuse. Without a traceparent we start a fresh trace
// (n8n's own spans then land in a separate trace).
const req = $input.first().json;
const h = req.headers || {};
const b = req.body || {};
const hex = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const m = /^00-([0-9a-f]{32})-([0-9a-f]{16})-[0-9a-f]{2}$/.exec(String(h.traceparent || ''));
const customerId = String(b.customer_id || 'anonymous');
const channel = String(b.channel || 'unknown');
return [{
  json: {
    trace_id: m ? m[1] : hex(32),
    root_span_id: m ? m[2] : hex(16),
    joined_caller_trace: Boolean(m),
    // Root starts when the caller sent the request (X-Request-Start: t=<epoch ms>), so it
    // encloses n8n's workflow.execute span; otherwise when this node ran.
    started_ns: String(Number(String(h['x-request-start'] || '').replace(/^t=/, '')) || Date.now()) + '000000',
    customer_id: customerId,
    channel,
    session_id: String(b.session_id || `${channel}-${customerId}-${new Date().toISOString().slice(0, 10)}`),
    text: String(b.text || ''),
    execution_id: String($execution.id),
    workflow_id: String($workflow.id),
    workflow_name: String($workflow.name),
  },
}];

// Mask PII before the text reaches the model or Langfuse. Card numbers are
// Luhn-checked so order ids and amounts survive; the last 4 digits stay.
const ctx = $('Trace context').first().json;
const startNs = String(Date.now()) + '000000';
const counts = { card_number: 0, iban: 0, email: 0, phone: 0 };
const luhn = (digits) => {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9; }
    sum += d;
  }
  return sum % 10 === 0;
};
let t = ctx.text;
t = t.replace(/\b(?:\d[ -]?){12,18}\d\b/g, (m) => {
  const d = m.replace(/\D/g, '');
  if (d.length < 13 || d.length > 19 || !luhn(d)) return m;
  counts.card_number++;
  return `[CARD ****${d.slice(-4)}]`;
});
t = t.replace(/\b[A-Z]{2}\d{2}(?: ?[A-Z0-9]{4}){2,7}(?: ?[A-Z0-9]{1,3})?\b/g, () => { counts.iban++; return '[IBAN]'; });
t = t.replace(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g, () => { counts.email++; return '[EMAIL]'; });
t = t.replace(/\+?\d[\d ()-]{8,}\d/g, (m) => {
  if (m.replace(/\D/g, '').length < 10) return m; // dates, amounts, short refs survive
  counts.phone++;
  return '[PHONE]';
});
const found = Object.values(counts).reduce((a, b) => a + b, 0);
return [{ json: { text_masked: t, pii_counts: counts, pii_found: found, mask_start_ns: startNs, mask_end_ns: String(Date.now()) + '000000' } }];

// Validate the model's JSON against the allowed labels (fail closed to 'other').
const res = $input.first().json;
const text = (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
let parsed = {};
try { parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) { parsed = {}; }
const CATEGORIES = ['card_fraud', 'fees', 'transfers', 'service', 'other'];
const SEVERITIES = ['low', 'medium', 'high'];
const triage = {
  category: CATEGORIES.includes(parsed.category) ? parsed.category : 'other',
  severity: SEVERITIES.includes(parsed.severity) ? parsed.severity : 'medium',
  regulatory_escalation: parsed.regulatory_escalation === true,
  rationale: String(parsed.rationale || '').slice(0, 300),
};
const now = String(Date.now()) + '000000';
return [{ json: {
  triage,
  parse_ok: Object.keys(parsed).length > 0,
  classify: { id: res.id, model: res.model, usage: res.usage || {}, stop_reason: res.stop_reason, output_text: text, end_ns: now },
  reply_start_ns: now,
} }];

