// Report the LLM steps to Langfuse as OpenTelemetry spans (OTLP/JSON) using
// Langfuse's attribute conventions. Same trace id as n8n's own spans.
const ctx = $('Trace context').first().json;
const pii = $('Mask PII').first().json;
const prompt = $('Get prompt (Langfuse)').first().json;
const cls = $('Parse classification').first().json;
const reply = $input.first().json; // raw Anthropic response of 'Draft reply'
const endNs = String(Date.now()) + '000000';
const replyText = (reply.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
const hex = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const S = (k, v) => ({ key: k, value: { stringValue: String(v) } });
const J = (k, v) => S(k, JSON.stringify(v));
const A = (k, arr) => ({ key: k, value: { arrayValue: { values: arr.map((x) => ({ stringValue: String(x) })) } } });
const usage = (u) => ({ input: (u && u.input_tokens) || 0, output: (u && u.output_tokens) || 0 });

const tags = ['channel:n8n', 'team:customer-care', `intake:${ctx.channel}`];
if (cls.triage.regulatory_escalation) tags.push('regulatory-escalation');
// Trace-level attributes go on EVERY span we emit (Langfuse filters per observation).
const traceAttrs = [
  S('langfuse.trace.name', 'n8n-complaint-triage'),
  S('user.id', ctx.customer_id),
  S('session.id', ctx.session_id),
  A('langfuse.trace.tags', tags),
  S('langfuse.environment', 'production'),
];
const span = (spanId, parentSpanId, name, start, end, attrs, isError) => ({
  traceId: ctx.trace_id,
  spanId,
  ...(parentSpanId ? { parentSpanId } : {}),
  name,
  kind: 1,
  startTimeUnixNano: start,
  endTimeUnixNano: end,
  attributes: [...traceAttrs, ...attrs],
  status: { code: isError ? 2 : 1 },
});

const response = {
  trace_id: ctx.trace_id,
  customer_id: ctx.customer_id,
  category: cls.triage.category,
  severity: cls.triage.severity,
  regulatory_escalation: cls.triage.regulatory_escalation,
  rationale: cls.triage.rationale,
  reply: replyText,
  pii_masked: pii.pii_counts,
  n8n_execution_id: ctx.execution_id,
};
const execUrl = `http://localhost:5678/workflow/${ctx.workflow_id}/executions/${ctx.execution_id}`;

const spans = [
  span(ctx.root_span_id, null, 'n8n-complaint-triage', ctx.started_ns, endNs, [
    J('langfuse.observation.input', { customer_id: ctx.customer_id, channel: ctx.channel, text: pii.text_masked }),
    J('langfuse.observation.output', response),
    S('langfuse.trace.metadata.category', cls.triage.category),
    S('langfuse.trace.metadata.severity', cls.triage.severity),
    S('langfuse.trace.metadata.regulatory_escalation', String(cls.triage.regulatory_escalation)),
    S('langfuse.trace.metadata.n8n_workflow', ctx.workflow_name),
    S('langfuse.trace.metadata.n8n_execution_id', ctx.execution_id),
    S('langfuse.trace.metadata.n8n_execution_url', execUrl),
    S('langfuse.trace.metadata.joined_caller_trace', String(ctx.joined_caller_trace)),
  ]),
  span(hex(16), ctx.root_span_id, 'mask-pii', pii.mask_start_ns, pii.mask_end_ns, [
    S('langfuse.observation.type', 'guardrail'),
    S('langfuse.observation.level', pii.pii_found > 0 ? 'WARNING' : 'DEFAULT'),
    J('langfuse.observation.input', { checks: Object.keys(pii.pii_counts) }),
    J('langfuse.observation.output', { masked: pii.pii_counts }),
    S('langfuse.observation.metadata.n8n_node', 'Mask PII'),
  ]),
  span(hex(16), ctx.root_span_id, 'classify-complaint', pii.mask_end_ns, cls.classify.end_ns, [
    S('langfuse.observation.type', 'generation'),
    S('langfuse.observation.model.name', cls.classify.model || (prompt.config && prompt.config.model) || 'unknown'),
    J('langfuse.observation.model.parameters', { temperature: (prompt.config && prompt.config.temperature) ?? 0, max_tokens: (prompt.config && prompt.config.max_tokens) || 300 }),
    J('langfuse.observation.usage_details', usage(cls.classify.usage)),
    J('langfuse.observation.input', [{ role: 'system', content: prompt.prompt }, { role: 'user', content: pii.text_masked }]),
    J('langfuse.observation.output', { role: 'assistant', content: cls.classify.output_text }),
    S('langfuse.observation.prompt.name', prompt.name),
    { key: 'langfuse.observation.prompt.version', value: { intValue: String(prompt.version) } },
    S('langfuse.observation.metadata.n8n_node', 'Classify complaint'),
    S('langfuse.observation.metadata.parse_ok', String(cls.parse_ok)),
    S('langfuse.observation.metadata.stop_reason', String(cls.classify.stop_reason)),
  ], !cls.parse_ok),
  span(hex(16), ctx.root_span_id, 'draft-reply', cls.reply_start_ns, endNs, [
    S('langfuse.observation.type', 'generation'),
    S('langfuse.observation.model.name', reply.model || 'claude-sonnet-4-6'),
    J('langfuse.observation.model.parameters', { temperature: 0.3, max_tokens: 400 }),
    J('langfuse.observation.usage_details', usage(reply.usage)),
    J('langfuse.observation.input', [{ role: 'user', content: `Category: ${cls.triage.category}, severity: ${cls.triage.severity}, regulatory escalation: ${cls.triage.regulatory_escalation}\n\n${pii.text_masked}` }]),
    J('langfuse.observation.output', { role: 'assistant', content: replyText }),
    S('langfuse.observation.metadata.n8n_node', 'Draft reply'),
    S('langfuse.observation.metadata.stop_reason', String(reply.stop_reason)),
  ]),
];

const otlp = { resourceSpans: [{
  resource: { attributes: [S('service.name', 'n8n-northwind'), S('n8n.workflow.name', ctx.workflow_name)] },
  scopeSpans: [{ scope: { name: 'n8n-workflow-langfuse-reporter', version: '1.0.0' }, spans }],
}] };
return [{ json: { response, otlp } }];
